146	void enqueuePendingClienstToIOThreads(client *c) {
147	    serverAssert(c->tid != IOTHREAD_MAIN_THREAD_ID &&
148	                 c->running_tid == IOTHREAD_MAIN_THREAD_ID);
149	
150	    if (c->flags & CLIENT_PENDING_WRITE) {
151	        c->flags &= ~CLIENT_PENDING_WRITE;
152	        listUnlinkNode(server.clients_pending_write, &c->clients_pending_write_node);
153	    }
154	    if (c->flags & CLIENT_SLAVE) {
155	        serverAssert(c->ref_repl_buf_node != NULL);
156	
157	        c->io_repl_ack_time = c->repl_ack_time;
158	        c->io_curr_repl_node = c->ref_repl_buf_node;
159	        c->io_curr_block_pos = c->ref_block_pos;
160	        c->io_bound_repl_node = listLast(server.repl_buffer_blocks);
161	        c->io_bound_block_pos = ((replBufBlock*)listNodeValue(c->io_bound_repl_node))->used;
162	    }
163	    if (c->flags & CLIENT_MASTER) {
164	        c->io_read_reploff = c->read_reploff;
165	        c->io_lastinteraction = c->lastinteraction;
166	    }
167	
168	    /* Check here prevents data races with IO thread which may also check
169	     * this flag. */
170	    if (!(c->io_flags & CLIENT_IO_COMPRESSION_ENABLED)) {
171	        if (c->compression_level > 0) {
172	            if (!clientEnableCompression(c, COMPRESS)) {
173	                /* Failing to initialize compression is unrecoverable for this
174	                 * client. Drop it so it can retry. We are on the main thread
175	                 * (possibly iterating server.slaves), so schedule an async
176	                 * close to avoid freeing the client under an active iterator. */
177	                serverLog(LL_WARNING,
178	                    "Failed to enable compression for client #%llu. Closing connection...",
179	                    (unsigned long long)c->id);
180	                freeClientAsync(c);
181	                return;
182	            }
183	        }
184	        if (c->flags & CLIENT_MASTER) {
185	            enableMasterClientDecompressionIfNeeded(c);
186	        }
187	    }
188	
189	    c->running_tid = c->tid;
190	    listAddNodeHead(mainThreadPendingClientsToIOThreads[c->tid], c);
191	}
