193	/* Unbind connection of client from io thread event loop, write and read handlers
194	 * also be removed, ensures that we can operate the client safely. */
195	void unbindClientFromIOThreadEventLoop(client *c) {
196	    serverAssert(c->tid != IOTHREAD_MAIN_THREAD_ID &&
197	                 c->running_tid == IOTHREAD_MAIN_THREAD_ID);
198	    /* If the client is not bound to an event loop there is nothing to do,
199	     * unless the client uses repl compression in which case we need to unlink
200	     * it from IO Thread compression_clients list. */
201	    if (!connHasEventLoop(c->conn) && !c->compression_state) return;
202	
203	    /* As calling in main thread, we should pause the io thread to make it safe. */
204	    pauseIOThread(c->tid);
205	    clientCompressionPendingRemove(c);
206	    connUnbindEventLoop(c->conn);
207	    IOThread *t = &IOThreads[c->tid];
208	    /* We need to remove the client from the compression_clients list so it
209	     * won't be processed in IOThreadCompressionCron anymore */
210	    if (c->io_thread_compression_clients_node) {
211	        listDelNode(t->compression_clients, c->io_thread_compression_clients_node);
212	        c->io_thread_compression_clients_node = NULL;
213	        clientDisableCompression(c);
214	    }
215	    resumeIOThread(c->tid);
216	}
