242	/* If the client is managed by IO thread, we should fetch it from IO thread
243	 * and then main thread will can process it. Just like IO Thread transfers
244	 * the client to the main thread for processing. */
245	void fetchClientFromIOThread(client *c) {
246	    serverAssert(c->tid != IOTHREAD_MAIN_THREAD_ID &&
247	                 c->running_tid != IOTHREAD_MAIN_THREAD_ID);
248	    pauseIOThread(c->tid);
249	    /* Remove the client from clients list of IO thread or main thread. */
250	    if (c->io_thread_client_list_node) {
251	        listDelNode(IOThreads[c->tid].clients, c->io_thread_client_list_node);
252	        c->io_thread_client_list_node = NULL;
253	    } else {
254	        list *clients[5] = {
255	            IOThreads[c->tid].pending_clients,
256	            IOThreads[c->tid].pending_clients_to_main_thread,
257	            mainThreadPendingClients[c->tid],
258	            mainThreadProcessingClients[c->tid],
259	            mainThreadPendingClientsToIOThreads[c->tid]
260	        };
261	        for (int i = 0; i < 5; i++) {
262	            listNode *ln = listSearchKey(clients[i], c);
263	            if (ln) {
264	                listDelNode(clients[i], ln);
265	                /* Client only can be in one client list. */
266	                break;
267	            }
268	        }
269	    }
270	    /* Unbind connection of client from io thread event loop. */
271	    clientCompressionPendingRemove(c);
272	    connUnbindEventLoop(c->conn);
273	    /* Now main thread can process it. */
274	    resumeIOThread(c->tid);
275	
276	    /* Keep the client in main thread. */
277	    c->running_tid = IOTHREAD_MAIN_THREAD_ID;
278	    keepClientInMainThread(c);
279	}
