281	/* For some clients, we must handle them in the main thread, since there is
282	 * data race to be processed in IO threads.
283	 *
284	 * - Close ASAP, we must free the client in main thread.
285	 * - Pubsub, monitor, blocked, tracking clients, main thread may
286	 *   directly write them a reply when conditions are met.
287	 * - Script command with debug may operate connection directly.
288	 * - Master/Replica are only handled by IO thread when RDB replication is
289	 *   completed. Note we need to check them after checking for other flags
290	 *   that may overlap with CLIENT_MASTER/SLAVE - CLOSE_ASAP, MONITOR,
291	 *   (UN)BLOCKED, TRACKING. */
292	int isClientMustHandledByMainThread(client *c) {
293	    if (c->flags & (CLIENT_CLOSE_ASAP |
294	                    CLIENT_PUBSUB | CLIENT_MONITOR | CLIENT_BLOCKED |
295	                    CLIENT_UNBLOCKED | CLIENT_TRACKING | CLIENT_LUA_DEBUG |
296	                    CLIENT_LUA_DEBUG_SYNC | CLIENT_ASM_MIGRATING |
297	                    CLIENT_ASM_IMPORTING))
298	    {
299	        return 1;
300	    }
301	
302	    /* If RDB replication is done it's safe to move the master client to an IO thread.
303	     * Note that we keep the master client in main thread during failover so as
304	     * not to slow down the failover process by waiting the master replication
305	     * cron in IO thread. */
306	    if (c->flags & CLIENT_MASTER &&
307	        server.repl_state == REPL_STATE_CONNECTED &&
308	        server.repl_rdb_ch_state == REPL_RDB_CH_STATE_NONE &&
309	        server.failover_state == NO_FAILOVER)
310	    {
311	        return 0;
312	    }
313	
314	    /* If RDB replication is done for this slave it's safe to move it to an IO thread
315	     * Note that we also check if the ref_repl_buf_node is initialized in order
316	     * to prevent race conditions with main thread when it feeds the replication
317	     * buffer. */
318	    if (c->flags & CLIENT_SLAVE &&
319	        (c->replstate == SLAVE_STATE_ONLINE ||
320	         c->replstate == SLAVE_STATE_SEND_BULK_AND_STREAM) &&
321	        c->repl_start_cmd_stream_on_ack == 0 &&
322	        c->ref_repl_buf_node != NULL)
323	    {
324	        return 0;
325	    }
326	
327	    if (c->flags & (CLIENT_MASTER | CLIENT_SLAVE)) return 1;
328	
329	    return 0;
330	}
