363	/* If updating maxclients config, we not only resize the event loop of main thread
364	 * but also resize the event loop of all io threads, and if one thread is failed,
365	 * it is failed totally, since a fd can be distributed into any IO thread. */
366	int resizeAllIOThreadsEventLoops(size_t newsize) {
367	    int result = AE_OK;
368	    if (server.io_threads_num <= 1) return result;
369	
370	    /* To make context safe. */
371	    pauseAllIOThreads();
372	    for (int i = 1; i < server.io_threads_num; i++) {
373	        IOThread *t = &IOThreads[i];
374	        if (aeResizeSetSize(t->el, newsize) == AE_ERR)
375	            result = AE_ERR;
376	    }
377	    resumeAllIOThreads();
378	    return result;
379	}
