381	/* In the main thread, we may want to operate data of io threads, maybe uninstall
382	 * event handler, access query/output buffer or resize event loop, we need a clean
383	 * and safe context to do that. We pause io thread in IOThreadBeforeSleep, do some
384	 * jobs and then resume it. To avoid thread suspended, we use busy waiting to confirm
385	 * the target status. Besides we use atomic variable to make sure memory visibility
386	 * and ordering.
387	 *
388	 * Make sure that only the main thread can call these function,
389	 *  - pauseIOThread, resumeIOThread
390	 *  - pauseAllIOThreads, resumeAllIOThreads
391	 *  - pauseIOThreadsRange, resumeIOThreadsRange
392	 *
393	 * The main thread will pause the io thread, and then wait for the io thread to
394	 * be paused. The io thread will check the paused status in IOThreadBeforeSleep,
395	 * and then pause itself.
396	 *
397	 * The main thread will resume the io thread, and then wait for the io thread to
398	 * be resumed. The io thread will check the paused status in IOThreadBeforeSleep,
399	 * and then resume itself.
400	 */
401	
402	/* We may pause the same io thread nestedly, so we need to record the times of
403	 * pausing, and only when the times of pausing is 0, we can pause the io thread,
404	 * and only when the times of pausing is 1, we can resume the io thread. */
405	static int PausedIOThreads[IO_THREADS_MAX_NUM] = {0};
406	
407	/* Pause the specific range of io threads, and wait for them to be paused. */
408	void pauseIOThreadsRange(int start, int end) {
409	    if (!server.io_threads_active) return;
410	    serverAssert(start >= 1 && end < server.io_threads_num && start <= end);
411	    serverAssert(pthread_equal(pthread_self(), server.main_thread_id));
412	
413	    /* Try to make all io threads paused in parallel */
414	    for (int i = start; i <= end; i++) {
415	        PausedIOThreads[i]++;
416	        /* Skip if already paused */
417	        if (PausedIOThreads[i] > 1) continue;
418	
419	        int paused;
420	        atomicGetWithSync(IOThreads[i].paused, paused);
421	        /* Don't support to call reentrant */
422	        serverAssert(paused == IO_THREAD_UNPAUSED);
423	        atomicSetWithSync(IOThreads[i].paused, IO_THREAD_PAUSING);
424	        /* Just notify io thread, no actual job, since io threads check paused
425	         * status in IOThreadBeforeSleep, so just wake it up if polling wait. */
426	        triggerEventNotifier(IOThreads[i].pending_clients_notifier);
427	    }
428	
429	    /* Wait for all io threads paused */
430	    for (int i = start; i <= end; i++) {
431	        if (PausedIOThreads[i] > 1) continue;
432	        int paused = IO_THREAD_PAUSING;
433	        while (paused != IO_THREAD_PAUSED) {
434	            atomicGetWithSync(IOThreads[i].paused, paused);
435	        }
436	    }
437	}
438	
439	/* Resume the specific range of io threads, and wait for them to be resumed. */
440	void resumeIOThreadsRange(int start, int end) {
441	    if (!server.io_threads_active) return;
442	    serverAssert(start >= 1 && end < server.io_threads_num && start <= end);
443	    serverAssert(pthread_equal(pthread_self(), server.main_thread_id));
444	
445	    for (int i = start; i <= end; i++) {
446	        serverAssert(PausedIOThreads[i] > 0);
447	        PausedIOThreads[i]--;
448	        if (PausedIOThreads[i] > 0) continue;
449	
450	        int paused;
451	        /* Check if it is paused, since we must call 'pause' and
452	         * 'resume' in pairs */
453	        atomicGetWithSync(IOThreads[i].paused, paused);
454	        serverAssert(paused == IO_THREAD_PAUSED);
455	        /* Resume */
456	        atomicSetWithSync(IOThreads[i].paused, IO_THREAD_RESUMING);
457	        while (paused != IO_THREAD_UNPAUSED) {
458	            atomicGetWithSync(IOThreads[i].paused, paused);
459	        }
460	    }
461	}
462	
463	/* The IO thread checks whether it is being paused, and if so, it pauses itself
464	 * and waits for resuming, corresponding to the pause/resumeIOThread* functions.
465	 * Currently, this is only called in IOThreadBeforeSleep, as there are no pending
466	 * I/O events at this point, with a clean context. */
467	void handlePauseAndResume(IOThread *t) {
468	    int paused;
469	    /* Check if i am being paused. */
470	    atomicGetWithSync(t->paused, paused);
471	    if (paused == IO_THREAD_PAUSING) {
472	        atomicSetWithSync(t->paused, IO_THREAD_PAUSED);
473	        /* Wait for resuming */
474	        while (paused != IO_THREAD_RESUMING) {
475	            atomicGetWithSync(t->paused, paused);
476	        }
477	        atomicSetWithSync(t->paused, IO_THREAD_UNPAUSED);
478	    }
479	}
480	
481	/* Pause the specific io thread, and wait for it to be paused. */
482	void pauseIOThread(int id) {
483	    pauseIOThreadsRange(id, id);
484	}
485	
486	/* Resume the specific io thread, and wait for it to be resumed. */
487	void resumeIOThread(int id) {
488	    resumeIOThreadsRange(id, id);
489	}
490	
491	/* Pause all io threads, and wait for them to be paused. */
492	void pauseAllIOThreads(void) {
493	    pauseIOThreadsRange(1, server.io_threads_num-1);
494	}
495	
496	/* Resume all io threads, and wait for them to be resumed. */
497	void resumeAllIOThreads(void) {
498	    resumeIOThreadsRange(1, server.io_threads_num-1);
499	}
