717	/* When the io thread finishes processing the client with the read event, it will
718	 * notify the main thread through event triggering in IOThreadBeforeSleep. The main
719	 * thread handles the event through this function. */
720	void handleClientsFromIOThread(struct aeEventLoop *el, int fd, void *ptr, int mask) {
721	    UNUSED(el);
722	    UNUSED(mask);
723	
724	    IOThread *t = ptr;
725	
726	    /* Handle fd event first. */
727	    serverAssert(fd == getReadEventFd(mainThreadPendingClientsNotifiers[t->id]));
728	    handleEventNotifier(mainThreadPendingClientsNotifiers[t->id]);
729	
730	    /* Process the clients from IO threads. */
731	    processClientsFromIOThread(t);
732	}
733	
734	/* In the new threaded io design, one thread may process multiple clients, so when
735	 * an io thread notifies the main thread of an event, there may be multiple clients
736	 * with commands that need to be processed. But in the event handler function
737	 * handleClientsFromIOThread may be blocked when processing the specific command,
738	 * the previous clients can not get a reply, and the subsequent clients can not be
739	 * processed, so we need to handle this scenario in beforeSleep. The function is to
740	 * process the commands of subsequent clients from io threads. And another function
741	 * sendPendingClientsToIOThreads make sure clients from io thread can get replies.
742	 * See also beforeSleep.
743	 * 
744	 * In beforeSleep, we also call this function to handle the clients that are
745	 * transferred from io threads without notification. */
746	int processClientsOfAllIOThreads(void) {
747	    int processed = 0;
748	    for (int i = 1; i < server.io_threads_num; i++) {
749	        processed += processClientsFromIOThread(&IOThreads[i]);
750	    }
751	    return processed;
752	}
753	
754	/* After the main thread processes the clients, it will send the clients back to
755	 * io threads to handle, and fire an event, the io thread handles the event by
756	 * this function. */
757	void handleClientsFromMainThread(struct aeEventLoop *ae, int fd, void *ptr, int mask) {
758	    UNUSED(ae);
759	    UNUSED(mask);
760	
761	    IOThread *t = ptr;
762	
763	    /* Handle fd event first. */
764	    serverAssert(fd == getReadEventFd(t->pending_clients_notifier));
765	    handleEventNotifier(t->pending_clients_notifier);
766	
767	    /* Process the clients from main thread. */
768	    processClientsFromMainThread(t);
769	}
