 973	/* The main function of IO thread, it will run an event loop. The mian thread
 974	 * and IO thread will communicate through event notifier. */
 975	void *IOThreadMain(void *ptr) {
 976	    IOThread *t = ptr;
 977	    /* Claim a reserved used_memory accounting slot before any allocation. */
 978	    zmalloc_register_reserved_slot();
 979	    char thdname[16];
 980	    snprintf(thdname, sizeof(thdname), "io_thd_%d", t->id);
 981	    redis_set_thread_title(thdname);
 982	    redisSetCpuAffinity(server.server_cpulist);
 983	    makeThreadKillable();
 984	    aeSetBeforeSleepProc(t->el, IOThreadBeforeSleep);
 985	    aeSetAfterSleepProc(t->el, IOThreadAfterSleep);
 986	    aeMain(t->el);
 987	    return NULL;
 988	}
