1062	/* Kill the IO threads, TODO: release the applied resources. */
1063	void killIOThreads(void) {
1064	    if (server.io_threads_num <= 1) return;
1065	
1066	    int err, j;
1067	    for (j = 1; j < server.io_threads_num; j++) {
1068	        if (IOThreads[j].tid == pthread_self()) continue;
1069	        if (IOThreads[j].tid && pthread_cancel(IOThreads[j].tid) == 0) {
