 993	
 994	    server.io_threads_active = 1;
 995	
 996	    if (server.io_threads_num > IO_THREADS_MAX_NUM) {
 997	        serverLog(LL_WARNING,"Fatal: too many I/O threads configured. "
 998	                             "The maximum number is %d.", IO_THREADS_MAX_NUM);
 999	        exit(1);
1000	    }
1001	
1002	    /* Spawn and initialize the I/O threads. */
1003	    for (int i = 1; i < server.io_threads_num; i++) {
1004	        IOThread *t = &IOThreads[i];
1005	        t->id = i;
1006	        t->el = aeCreateEventLoop(server.maxclients+CONFIG_FDSET_INCR);
1007	        t->el->privdata[0] = t;
