1015	        atomicSetWithSync(t->running, 0);
1016	
1017	        pthread_mutexattr_t *attr = NULL;
1018	        #if defined(__linux__) && defined(__GLIBC__)
1019	        attr = zmalloc(sizeof(pthread_mutexattr_t));
1020	        pthread_mutexattr_init(attr);
1021	        pthread_mutexattr_settype(attr, PTHREAD_MUTEX_ADAPTIVE_NP);
1022	        #endif
1023	        pthread_mutex_init(&t->pending_clients_mutex, attr);
1024	
1025	        t->pending_clients_notifier = createEventNotifier();
1026	        if (aeCreateFileEvent(t->el, getReadEventFd(t->pending_clients_notifier),
1027	                              AE_READABLE, handleClientsFromMainThread, t) != AE_OK)
1028	        {
1029	            serverLog(LL_WARNING, "Fatal: Can't register file event for IO thread notifications.");
1030	            exit(1);
1031	        }
1032	
1033	        /* This is the timer callback of the IO thread, used to gradually handle 
