1038	        }
1039	
1040	        /* Create IO thread */
1041	        if (pthread_create(&t->tid, NULL, IOThreadMain, (void*)t) != 0) {
1042	            serverLog(LL_WARNING, "Fatal: Can't initialize IO thread.");
1043	            exit(1);
1044	        }
1045	
1046	        /* For main thread */
1047	        mainThreadPendingClientsToIOThreads[i] = listCreate();
1048	        mainThreadPendingClients[i] = listCreate();
1049	        mainThreadProcessingClients[i] = listCreate();
1050	        pthread_mutex_init(&mainThreadPendingClientsMutexes[i], attr);
1051	        mainThreadPendingClientsNotifiers[i] = createEventNotifier();
1052	        if (aeCreateFileEvent(server.el, getReadEventFd(mainThreadPendingClientsNotifiers[i]),
1053	                              AE_READABLE, handleClientsFromIOThread, t) != AE_OK)
1054	        {
1055	            serverLog(LL_WARNING, "Fatal: Can't register file event for main thread notifications.");
1056	            exit(1);
1057	        }
1058	        if (attr) zfree(attr);
1059	    }
1060	}
