 463	/* The IO thread checks whether it is being paused, and if so, it pauses itself
 464	 * and waits for resuming, corresponding to the pause/resumeIOThread* functions.
 465	 * Currently, this is only called in IOThreadBeforeSleep, as there are no pending
 466	 * I/O events at this point, with a clean context. */
 467	void handlePauseAndResume(IOThread *t) {
 468	    int paused;
 469	    /* Check if i am being paused. */
 470	    atomicGetWithSync(t->paused, paused);
 471	    if (paused == IO_THREAD_PAUSING) {
 472	        atomicSetWithSync(t->paused, IO_THREAD_PAUSED);
 473	        /* Wait for resuming */
 474	        while (paused != IO_THREAD_RESUMING) {
 475	            atomicGetWithSync(t->paused, paused);
 476	        }
 477	        atomicSetWithSync(t->paused, IO_THREAD_UNPAUSED);
 478	    }
 479	}
