 501	/* Add the pending clients to the list of IO threads, and trigger an event to
 502	 * notify io threads to handle. */
 503	int sendPendingClientsToIOThreads(void) {
 504	    int processed = 0;
 505	    for (int i = 1; i < server.io_threads_num; i++) {
 506	        int len = listLength(mainThreadPendingClientsToIOThreads[i]);
 507	        if (len > 0) {
 508	            IOThread *t = &IOThreads[i];
 509	            pthread_mutex_lock(&t->pending_clients_mutex);
 510	            listJoin(t->pending_clients, mainThreadPendingClientsToIOThreads[i]);
 511	            pthread_mutex_unlock(&t->pending_clients_mutex);
 512	            /* Trigger an event, maybe an error is returned when buffer is full
 513	             * if using pipe, but no worry, io thread will handle all clients
 514	             * in list when receiving a notification. */
 515	            triggerEventNotifier(t->pending_clients_notifier);
 516	        }
 517	        processed += len;
 518	    }
 519	    return processed;
